    "wgc.pageTitle": "Weighted Grade Calculator - Calculate Grades With Weights",
    "wgc.pageDesc": "Free weighted grade calculator to compute course averages using category weights or total points. Includes automatic weight normalization and drop-lowest score.",
    "wgc.eyebrow": "Syllabus Category Averaging",
    "wgc.h1": "Weighted Grade Calculator",
    "wgc.lead": "Accurately calculate your weighted class average. Add homework, quizzes, tests, labs, and attendance with individual category percentage weights. Supports automatic normalization if incomplete weights sum to less than 100%.",
