    "wgc.colCalc": "Calculated",
    "wgc.addRowBtn": "Add Assignment Row",
    "wgc.howToTitle": "How to Calculate a Weighted Grade",
    "wgc.howToP1": "When assignments carry different degrees of importance (for example, exams count more than daily homework), your grade cannot be computed by simply averaging your raw scores. Instead, you calculate a weighted arithmetic mean:",
    "wgc.howToFormula": "Weighted Grade (%) = Σ[(Score ÷ Max) × Weight] ÷ ΣWeight",
    "wgc.midsemTitle": "Automatic Mid-Semester Normalization",
    "wgc.midsemP1": "During the middle of a school term, the assignments completed so far rarely add up to 100% of the course syllabus (e.g., only 65% of coursework has been graded). Our calculator automatically handles this by dividing your accumulated weighted points by the active completed weight, giving you an accurate reflection of your true current standing rather than an artificially depressed score.",
