    "trust.getInTouch": "Contáctanos →",
    "guide.s1Title": "¿Qué es una Calculadora de Calificaciones Final y Cómo Funciona?",
    "guide.s1P1": "Mantener el control de tu rendimiento académico requiere saber exactamente dónde estás antes de la semana de exámenes finales. Una calculadora de calificaciones final es una herramienta académica esencial para eliminar la incertidumbre en tus materias.",
    "guide.s1P2": "En Grade Calculator FinalX combinamos una calculadora de notas intuitiva con un planificador de examen final preciso. Procesa ponderaciones, calificaciones y objetivos en tiempo real sin fórmulas complicadas.",
    "guide.s2Title": "Calculadora de Notas Ponderadas vs. Calculadora de Promedio Simple",
    "guide.s2P1": "Muchos estudiantes calculan erróneamente sus notas usando un promedio aritmético simple. Sin embargo, la gran mayoría de programas académicos utilizan un sistema ponderado por porcentajes.",
    "guide.s2P2": "Con nuestra calculadora ponderada puedes asignar el peso correspondiente a cada categoría:",
    "guide.s2Li1": "Ponderación Porcentual: Tareas 20%, exámenes parciales 30% y examen final 50%.",
    "guide.s2Li2": "Sistema de Puntos Totales: Puntos obtenidos divididos entre puntos posibles.",
    "guide.s2Li3": "Descarte de Nota Menor: Elimina automáticamente la peor calificación de tareas o pruebas cortas.",
    "guide.s2P3": "Garantiza que los exámenes de mayor valor tengan su impacto numérico real en tu promedio.",
    "guide.s3Title": "Uso de la Calculadora de Examen Final para Alcanzar tu Nota Deseada",
    "guide.s3P1": "La pregunta más común antes de finalizar el período es: \"¿Qué nota necesito en mi examen final para sacar una A o aprobar?\"",
    "guide.s3P2": "Nuestra calculadora utiliza la fórmula algebraica comprobada:",
    "guide.s3Formula": "Nota Requerida = (Nota Final Deseada − Nota Actual × (1 − Peso del Examen)) / Peso del Examen",
    "guide.s3P3": "Nuestra matriz de escenarios compara tu promedio actual con toda la escala de notas y te indica la viabilidad en tiempo real.",
    "guide.s4Title": "Calculadora de Notas Universitarias y Planificación de GPA Semestral",
    "guide.s4P1": "Además de cursos individuales, los estudiantes necesitan monitorear su GPA semestral y acumulado.",
    "guide.s4P2": "Soporta escalas estándar 4.0, honores (+0.5) y cursos avanzados AP (+1.0).",
    "guide.s4P3": "Utiliza el control deslizante What-If para simular diferentes notas antes de rendir las evaluaciones.",
