    "trust.getInTouch": "お問い合わせ →",
    "guide.s1Title": "期末成績計算機とは？その仕組みと使い方",
    "guide.s1P1": "学業成績を向上させるためには、期末試験の前に現在の立ち位置を正確に把握しておくことが不可欠です。期末成績計算機は、日頃の課題や小テストの成績から現在の確定得点を可視化し、試験勉強の優先順位を決めるための重要な学習ツールです。",
    "guide.s1P2": "Grade Calculator FinalXでは、直感的な加重平均計算と高精度な期末試験目標プランナーを統合しています。複雑な手計算やスプレッドシートの手間をなくし、シラバスの配点比率を入力するだけでリアルタイムに計算します。",
    "guide.s2Title": "加重平均計算と単純平均計算の違い",
    "guide.s2P1": "多くの学生がすべての課題を同じ重要度で扱う単純平均で計算してしまいがちですが、大学の講義のほとんどは配点割合が異なる加重評価を採用しています。",
    "guide.s2P2": "加重平均計算機を使用すると、各項目に適切な配点割合を割り当てることができます：",
    "guide.s2Li1": "パーセント加重：宿題20%、中間試験30%、期末試験50%など、各得点に配点割合を乗算して計算します。",
    "guide.s2Li2": "総点数制：満点に対する獲得点数の比率で算出する点数制にもワンクリックで切り替え可能です。",
    "guide.s2Li3": "最低点除外ポリシー：複数回の小テストから最低得点を自動的に除外して計算する大学規定にも対応しています。",
    "guide.s2P3": "中間試験やレポートの真の重要度を正確に成績へ反映させることができます。",
    "guide.s3Title": "目標グレード（A/B）獲得に必要な期末試験スコアの算出",
    "guide.s3P1": "学期末に最も多い疑問は「希望のグレード（A評価）を取るには期末試験で何点必要か？」という点です。",
    "guide.s3P2": "当サイトは確実な代数計算式を用いて算出します：",
    "guide.s3Formula": "必要な期末試験得点 = (目標総合得点 − 現在の得点 × (1 − 期末試験配点割合)) / 期末試験配点割合",
    "guide.s3P3": "全評価基準（A+, A, B, C, D）に対する必要得点を一覧表で即座に比較でき、難易度判定バッジにより目標達成の現実性を一目で把握できます。",
    "guide.s4Title": "大学の履修科目と学期GPAプランニング",
    "guide.s4P1": "単一科目の計算だけでなく、学期全体の履修登録科目と累積GPAをまとめてシミュレーションできます。",
    "guide.s4P2": "標準4.0スケールに加え、オナーズ（+0.5）やAP科目（+1.0）の傾斜配点にも対応しています。",
    "guide.s4P3": "What-Ifスライダーにより、これからの試験で予想される点数を動かして、最終GPAの変動を視覚的に体験できます。",
    "status.complete": "配点割合100%分がすべて考慮されています。計算完了！",
