    "menu.sgpa": "学期GPA計算機",
    "gpa.desc": "科目単位数とレターグレード（4.0/5.0スケール）を入力し、大学の学期GPAおよび通算累計GPAを計算します。",
    "sgpa.desc": "各科目の単位数とグレードを入力し、学期ごとのGPAを4.0スケールで素早く算出します。",
    "icgpa.desc": "UGCおよびAICTEの10点満点CBCS方式に基づき、科目単位数とグレードポイントからCGPAを算出します。",
    "isgpa.desc": "インド大学のCBCS 10点満点基準に従い、単一学期のSGPAを正確に計算します。",
    "semcgpa.desc": "第1学期から第8学期までの各セメスターSGPAと単位数を入力し、学位全体の通算CGPAを計算します。",
    "cgpato.desc": "AICTE標準（9.5倍）、CBSE、ムンバイ大学、VTU等の公式換算式を用いて10点満点CGPAをパーセントに変換します。",
    "pcttocgpa.desc": "総合得点パーセンテージをUGCおよびAICTE基準の10点満点CGPAに換算します。",
