    "trust.getInTouch": "Nous contacter →",
    "guide.s1Title": "Qu’est-ce qu’un Calculateur de Notes Final et Comment Fonctionne-t-il ?",
    "guide.s1P1": "Maîtriser vos résultats académiques exige de connaître exactement votre position avant la semaine des examens finaux. Un calculateur de notes final est un outil indispensable pour éliminer les incertitudes.",
    "guide.s1P2": "Sur Grade Calculator FinalX, nous associons un calculateur de moyenne intuitif à un planificateur précis de note d’examen final.",
    "guide.s2Title": "Moyenne Pondérée vs Moyenne Simple",
    "guide.s2P1": "Calculer vos résultats avec une simple moyenne arithmétique fausse souvent votre vision si les matières ou devoirs possèdent des coefficients différents.",
    "guide.s2P2": "Notre outil pondéré permet d’attribuer le poids exact à chaque devoir ou examen :",
    "guide.s2Li1": "Pondération en Pourcentage : Devoirs 20%, partiels 30%, examen final 50%.",
    "guide.s2Li2": "Système par Points : Points obtenus divisés par les points totaux possibles.",
    "guide.s2Li3": "Exclusion de la Moins Bonne Note : Élimination automatique de votre note la plus faible.",
    "guide.s2P3": "Vos partiels et travaux majeurs reçoivent leur juste importance mathématique.",
    "guide.s3Title": "Utiliser le Calculateur d’Examen Final pour Viser Votre Mention",
    "guide.s3P1": "À l’approche des examens, chaque étudiant se demande : \"Quelle note dois-je obtenir au partiel final pour valider mon semestre ?\"",
    "guide.s3P2": "Notre formule algébrique calcule précisément ce seuil :",
    "guide.s3Formula": "Note Requise = (Note Finale Visée − Note Actuelle × (1 − Poids Examen)) / Poids Examen",
    "guide.s3P3": "La matrice comparative vous indique immédiatement la difficulté de l’objectif.",
