    "converter.pageTitle": "Tableau de Conversion de Notes - Échelles GPA, CGPA & %",
    "converter.pageDesc": "Comparez et convertissez les notes entre les systèmes US 4.0, pourcentages canadiens, CGPA indien 10.0 et ECTS européen.",
    "converter.eyebrow": "Conversion Académique Internationale",
    "converter.h1": "Matrice de Conversion des Notes",
    "converter.lead": "Guide de référence comparatif des échelles de notation internationales et universitaires.",
    "semcgpa.pageTitle": "Calculateur de CGPA par Semestre - Planificateur Cumulé",
    "semcgpa.pageDesc": "Saisissez les SGPA et crédits des semestres 1 à 8 pour calculer votre CGPA de diplôme cumulé.",
    "semcgpa.eyebrow": "Progression Semestrielle",
    "semcgpa.h1": "Calculateur de CGPA par Semestre",
    "semcgpa.lead": "Calculez votre CGPA cumulatif en renseignant le SGPA et les crédits validés pour chaque semestre.",
    "nav.home": "Accueil",
    "menu.cgpato": "CGPA en Pourcentage",
    "menu.pct_cgpa": "Pourcentage en CGPA",
