    "guide.s1Title": "Was ist ein Abschlussnotenrechner und wie funktioniert er?",
    "guide.s1P1": "Um die akademische Leistung optimal zu steuern, ist es entscheidend, vor den Prüfungen genau zu wissen, wo man steht. Ein Abschlussnotenrechner schafft Klarheit über Ihre aktuellen Teilleistungen.",
    "guide.s1P2": "Grade Calculator FinalX vereint einen einfachen Notenrechner mit einem exakten Prüfungsziel-Rechner.",
    "guide.s2Title": "Gewichteter Notenrechner vs. einfacher Durchschnitt",
    "guide.s2P1": "Viele Studierende rechnen mit einem einfachen Mittelwert, obwohl Prüfungsordnungen fast immer prozentual gewichtete Modulteile vorgeben.",
    "guide.s2P2": "Mit unserem Rechner weisen Sie jeder Leistung die korrekte Gewichtung zu:",
    "guide.s2Li1": "Prozentuale Gewichtung: Hausarbeiten 20%, Klausur 30%, Abschlussprüfung 50%.",
    "guide.s2Li2": "Punktesystem: Erreichte Punkte geteilt durch erreichbare Gesamtpunkte.",
    "guide.s2Li3": "Schlechteste Note streichen: Automatische Berücksichtigung von Streichnoten-Regelungen.",
    "guide.s2P3": "Wichtige Klausuren fließen mit ihrem echten numerischen Einfluss in das Gesamtergebnis ein.",
    "guide.s3Title": "Mit dem Prüfungsrechner die erforderliche Abschlussnote berechnen",
    "guide.s3P1": "Die zentrale Frage vor jeder Prüfungsphase lautet: \"Welche Note brauche ich in der Abschlussprüfung für eine 1,0 oder zum Bestehen?\"",
    "guide.s3P2": "Unsere integrierte Formel berechnet das exakte Ergebnis:",
    "guide.s3Formula": "Benötigte Prüfungsnote = (Zielnote − Aktuelle Note × (1 − Prüfungsgewichtung)) / Prüfungsgewichtung",
    "guide.s3P3": "Die Szenarien-Matrix zeigt für jede Notenstufe sofort die Machbarkeit an.",
    "guide.s4Title": "Universitäts-Noten und Semester-GPA Planung",
    "guide.s4P1": "Verwalten Sie alle Module des Semesters und Ihren Gesamt-Notendurchschnitt parallel.",
    "guide.s4P2": "Unterstützt ECTS-Credit-Points sowie standardisierte GPA-Skalen.",
    "guide.s4P3": "Der What-If Schieberegler simuliert Notenausgänge vor den Prüfungen.",
