    "about.title": "Über Uns - GradeCalculatorFinalX",
    "about.desc": "Erfahren Sie mehr über GradeCalculatorFinalX, unsere Mission für unkomplizierte Notenberechnungen und unsere datenschutzfreundlichen Tools.",
    "about.eyebrow": "Unsere Geschichte & Mission",
    "about.h1": "Über GradeCalculatorFinalX",
    "about.lead": "Mathematisch verifizierte, private und intuitive Notenberechnungstools für Schüler und Studierende weltweit.",
    "about.missionTitle": "Unsere Mission",
    "about.missionP1": "Bei GradeCalculatorFinalX (gradecalculatorfinalx.com) möchten wir die Unsicherheit und den Rechenaufwand bei Notenberechnungen vollständig beseitigen.",
    "about.missionP2": "Wir haben eine moderne, barrierefreie Plattform geschaffen, die komplexe Formeln in einfache interaktive Werkzeuge verwandelt.",
    "about.whyTitle": "Warum wir GradeCalculatorFinalX entwickelt haben",
    "about.whyP1": "Herkömmliche Notenberechnung über unübersichtliche Tabellen oder werbelastige Webseiten ist frustrierend. Wir wollten eine erstklassige Alternative bieten:",
    "about.whyLi1": "Vollständiger Datenschutz: Alle Berechnungen laufen clientseitig direkt in Ihrem Browser. Keine Speicherung auf Servern.",
    "about.whyLi2": "Volle Kursunterstützung: Nahtloser Wechsel zwischen prozentualen Gewichtungen und Punktesystemen inklusive automatischer Streichung der schlechtesten Note.",
    "about.whyLi3": "Prüfungsziel-Planung: Sofortige Berechnung der benötigten Note in der Abschlussprüfung für jede gewünschte Endnote.",
    "about.whyLi4": "Semester- & Gesamt-GPA: Berechnung nach Standard 4.0, Honors (+0.5) und AP/College (+1.0).",
    "about.precisionTitle": "Verlässliche Mathematische Präzision",
    "about.precisionP1": "Unsere Berechnungslogik wurde anhand internationaler akademischer Notenskalen verifiziert.",
    "about.precisionCard1Title": "Gewichteter Kategorierechner",
    "about.precisionCard1Desc": "Automatische Normalisierung aktiver Kursanteile während des laufenden Semesters.",
    "about.precisionCard2Title": "Prüfungsziel-Solver",
    "about.precisionCard2Desc": "Berechnet mit inverser Algebra die erforderliche Punktzahl in der Abschlussprüfung.",
    "about.communityTitle": "Für Studierende und Lehrkräfte entwickelt",
    "about.communityP1": "Regelmäßig von akademischen Beratern empfohlen, um Studienabschlüsse und Stipendien zu sichern.",
    "about.communityP2": "Haben Sie Feedback oder Kooperationsideen? Besuchen Sie unsere Kontaktseite.",
    "privacy.title": "Datenschutzerklärung - GradeCalculatorFinalX",
    "privacy.desc": "Datenschutzerklärung von GradeCalculatorFinalX. Erfahren Sie mehr über unseren Null-Tracking-Ansatz.",
    "privacy.eyebrow": "Transparenz & Sicherheit",
    "privacy.h1": "Datenschutzerklärung",
    "privacy.s1Title": "1. Einleitung & Datenschutzversprechen",
    "privacy.s1P1": "Willkommen bei GradeCalculatorFinalX. Wir schützen Ihre Privatsphäre ohne Kompromisse.",
    "privacy.s1P2": "Unsere Plattform arbeitet vollständig im Browser ohne Registrierungszwang oder Server-Datenbanken.",
    "privacy.s2Title": "2. Daten, die wir NICHT erfassen",
    "privacy.s2P1": "Wir erfassen, speichern oder übertragen keine persönlichen Notendaten:",
    "privacy.s2Li1": "Ihre Noten, Prüfungsergebnisse oder Gewichtungsprozente.",
    "privacy.s2Li2": "Ihre Kursnamen, Dozenten oder Universität.",
    "privacy.s2Li3": "Ihre Matrikelnummer oder Studiennachweise.",
    "privacy.s2Li4": "Passwörter oder Telefonnummern.",
    "privacy.s3Title": "3. LocalStorage & Lokale Datenspeicherung",
    "privacy.s3P1": "Für die automatische Sicherung Ihrer Kurse nutzt die Website die native LocalStorage-Technologie Ihres Browsers.",
    "privacy.s3P2": "Alle Einträge verbleiben streng auf Ihrem Gerät und können jederzeit gelöscht werden.",
    "privacy.s4Title": "4. Verschlüsselte URL-Freigabe",
    "privacy.s4P1": "Die Freigabefunktion kodiert Kursdaten in den URL-Hash (#data=...), der niemals an Server gesendet wird.",
    "privacy.s5Title": "5. Cookies & Server-Logs",
    "privacy.s5P1": "Wir verwenden keine Tracking-Cookies für kommerzielle Werbung.",
    "privacy.s6Title": "6. Schutz von Minderjährigen (COPPA)",
    "privacy.s6P1": "Wir erfassen wissentlich keine Daten von Kindern unter 13 Jahren und entsprechen den COPPA-Richtlinien.",
