    "guide.s1Title": "O que é uma Calculadora de Notas Final e Como Funciona?",
    "guide.s1P1": "Acompanhar o seu desempenho acadêmico exige saber exatamente sua situação antes do período de exames finais. Uma calculadora de notas final é indispensável para eliminar suposições.",
    "guide.s1P2": "No Grade Calculator FinalX unimos uma calculadora intuitiva de média ponderada com um planejador de exame final de alta precisão.",
    "guide.s2Title": "Calculadora de Média Ponderada vs. Média Simples",
    "guide.s2P1": "Muitos estudantes calculam notas usando uma média aritmética simples, desconsiderando que a maioria das faculdades utiliza pesos diferentes para cada avaliação.",
    "guide.s2P2": "Com nossa calculadora você atribui os pesos corretos para cada categoria:",
    "guide.s2Li1": "Ponderação em Porcentagem: Trabalhos 20%, provas parciais 30%, exame final 50%.",
    "guide.s2Li2": "Sistema por Pontos: Pontos acumulados divididos pelos pontos totais.",
    "guide.s2Li3": "Descarte de Menor Nota: Descarte automático da nota mais baixa em tarefas ou testes.",
    "guide.s2P3": "Garante a influência matemática real das avaliações de maior impacto.",
    "guide.s3Title": "Usando a Calculadora de Exame Final para Atingir a Média Desejada",
    "guide.s3P1": "A dúvida mais frequente é: \"Quanto preciso tirar na prova final para ser aprovado?\"",
    "guide.s3P2": "Nossa ferramenta aplica a fórmula algébrica precisa:",
    "guide.s3Formula": "Nota Necessária = (Nota Final Alvo − Nota Atual × (1 − Peso Exame)) / Peso Exame",
    "guide.s3P3": "A matriz de cenários compara sua média atual com todas as faixas de conceitos e indica a viabilidade.",
    "guide.s4Title": "Calculadora de Notas Universitárias e GPA Semestral",
    "guide.s4P1": "Avalie suas matérias simultaneamente e planeje seu GPA acumulado.",
    "guide.s4P2": "Suporte a créditos, escalas padrão 4.0 e matérias com honras.",
    "guide.s4P3": "Use o controle deslizante What-If para testar notas antes mesmo de realizar as avaliações.",
