    "about.title": "Sobre Nós - GradeCalculatorFinalX",
    "about.desc": "Conheça o GradeCalculatorFinalX, nossa missão de simplificar cálculos acadêmicos com total privacidade para estudantes em todo o mundo.",
    "about.eyebrow": "Nossa História e Missão",
    "about.h1": "Sobre o GradeCalculatorFinalX",
    "about.lead": "Apoiando estudantes do ensino médio e universitários com ferramentas de cálculo acadêmico precisas, privadas e intuitivas.",
    "about.missionTitle": "Nossa Missão",
    "about.missionP1": "No GradeCalculatorFinalX (gradecalculatorfinalx.com), nossa missão é eliminar a ansiedade e as dúvidas sobre médias acadêmicas.",
    "about.missionP2": "Criamos uma plataforma moderna e gratuita que transforma fórmulas complexas em ferramentas interativas fáceis de usar.",
    "about.whyTitle": "Por Que Criamos o GradeCalculatorFinalX?",
    "about.whyP1": "O cálculo tradicional de notas geralmente depende de planilhas complicadas ou sites cheios de anúncios. Queríamos algo melhor:",
    "about.whyLi1": "Privacidade Total: Todos os cálculos rodam diretamente no navegador do usuário (client-side). Nunca salvamos notas em servidores.",
    "about.whyLi2": "Suporte Completo: Alterne entre pesos percentuais e sistemas por pontos, com descarte automático da menor nota.",
    "about.whyLi3": "Planejamento de Exame Final: Saiba na hora a nota exata necessária no exame final para alcançar seu objetivo (A, B, C, Aprovação).",
    "about.whyLi4": "GPA Semestral e Acumulado: Suporte para escala 4.0 padrão, disciplinas de Honra (+0.5) e cursos avançados AP (+1.0).",
    "about.precisionTitle": "Precisão Matemática Confiável",
    "about.precisionP1": "Nossos algoritmos são matematicamente verificados conforme os padrões acadêmicos internacionais.",
    "about.precisionCard1Title": "Motor de Ponderação de Categorias",
    "about.precisionCard1Desc": "Normalização automática durante o semestre para refletir a situação real do aluno.",
    "about.precisionCard2Title": "Solucionador de Exame Alvo",
    "about.precisionCard2Desc": "Cálculo algébrico inverso para determinar a pontuação necessária na prova final.",
    "about.communityTitle": "Criado para Estudantes e Professores",
    "about.communityP1": "Amplamente utilizado por estudantes e orientadores pedagógicos para planejar desempenhos e bolsas de estudos.",
    "about.communityP2": "Tem sugestões de melhoria ou parcerias? Entre em contato conosco pela página de Contato.",
    "privacy.title": "Política de Privacidade - GradeCalculatorFinalX",
    "privacy.desc": "Política de Privacidade do GradeCalculatorFinalX. Saiba como garantimos a proteção completa dos dados dos estudantes.",
    "privacy.eyebrow": "Transparência & Segurança",
    "privacy.h1": "Política de Privacidade",
    "privacy.s1Title": "1. Introdução e Compromisso com a Privacidade",
    "privacy.s1P1": "Bem-vindo ao GradeCalculatorFinalX. Respeitamos e protegemos integralmente a sua privacidade.",
    "privacy.s1P2": "Nossa plataforma opera sem necessidade de cadastro ou envio de dados para servidores externos.",
    "privacy.s2Title": "2. Dados que NÃO Coletamos",
    "privacy.s2P1": "Ao usar nossas calculadoras, não coletamos nem armazenamos:",
    "privacy.s2Li1": "Suas notas, resultados de provas ou porcentagens de peso.",
    "privacy.s2Li2": "Nomes das disciplinas, professores ou faculdades.",
    "privacy.s2Li3": "Número de matrícula ou histórico escolar oficial.",
    "privacy.s2Li4": "Senhas ou números de telefone.",
    "privacy.s3Title": "3. LocalStorage e Armazenamento Local",
    "privacy.s3P1": "Para manter suas matérias salvas entre visitas, utilizamos a tecnologia nativa LocalStorage do seu navegador.",
    "privacy.s3P2": "Todos os dados ficam apenas no seu dispositivo e podem ser apagados a qualquer momento.",
    "privacy.s4Title": "4. Compartilhamento Criptografado por URL",
    "privacy.s4P1": "A função de compartilhamento codifica os dados no fragmento hash da URL (#data=...), processado estritamente no navegador.",
    "privacy.s5Title": "5. Cookies e Análises",
    "privacy.s5P1": "Não utilizamos cookies para publicidade comercial invasiva.",
    "privacy.s6Title": "6. Proteção de Menores (COPPA)",
    "privacy.s6P1": "Não coletamos informações de crianças menores de 13 anos e cumprimos integralmente as diretrizes da COPPA.",
    "privacy.s7Title": "7. Contato de Privacidade",
    "privacy.s7P1": "Em caso de dúvidas sobre privacidade, envie um e-mail para privacy@gradecalculatorfinalx.com.",
    "terms.title": "Termos e Condições - GradeCalculatorFinalX",
    "terms.desc": "Termos e Condições de Uso do GradeCalculatorFinalX. Diretrizes e isenção de responsabilidade.",
    "terms.eyebrow": "Termos Legais e Operacionais",
