    "terms.s1P1": "Ao acessar o GradeCalculatorFinalX, você concorda com estes Termos e Condições.",
    "terms.s2Title": "2. Finalidade Educacional e Isenção",
    "terms.s2P1": "As calculadoras são fornecidas apenas para fins de planejamento e autoavaliação acadêmica.",
    "terms.s2P2": "Recomendamos conferir as regras específicas de arredondamento junto à sua instituição de ensino.",
    "terms.s2P3": "Não emitimos certificados ou históricos oficiais.",
    "terms.s3Title": "3. Propriedade Intelectual",
    "terms.s3P1": "Todo o design, interface e códigos são protegidos por direitos autorais.",
    "terms.s4Title": "4. Conduta do Usuário",
    "terms.s4P1": "É proibido realizar ataques de sobrecarga ou engenharia reversa na plataforma.",
    "terms.s5Title": "5. Limitação de Responsabilidade",
    "terms.s5P1": "Não nos responsabilizamos por decisões acadêmicas decorrentes do uso das ferramentas.",
    "terms.s6Title": "6. Alterações nos Termos",
