    "gpa.desc": "Calcule seu GPA semestral e acumulado em escalas 4.0 e 5.0 com créditos de disciplinas e notas em letras.",
    "sgpa.desc": "Calcule o GPA do seu semestre inserindo os créditos e notas das matérias na escala padrão 4.0.",
    "icgpa.desc": "Calcule seu CGPA e SGPA na escala oficial CBCS de 10 pontos da UGC para universidades da Índia.",
    "isgpa.desc": "Calcule seu SGPA semestral conforme as diretrizes CBCS de 10 pontos da UGC.",
