    "cgpato.desc": "Converta seu CGPA de 10 pontos em porcentagem usando fórmulas oficiais da AICTE (9.5x), CBSE, Mumbai e VTU.",
    "pcttocgpa.desc": "Converta sua porcentagem geral em CGPA equivalente na escala de 10 pontos segundo padrões da UGC.",
