    "guide.s1P2": "Grade Calculator FinalX는 직관적인 가중 평균 계산과 정확한 기말고사 목표 플래너를 하나로 통합했습니다.",
    "guide.s2Title": "가중 성적 계산기 vs 단순 평균 계산기",
    "guide.s2P1": "모든 시험을 동일한 비중으로 취급하는 단순 평균으로 계산하면 실제 성적과 큰 오차가 발생합니다. 대부분의 강의는 항목별 가중치를 둡니다.",
    "guide.s2P2": "가중 성적 계산기를 사용하면 각 항목의 실제 반영 비율을 정확히 반영할 수 있습니다:",
    "guide.s2Li1": "백분율 가중치: 과제 20%, 중간고사 30%, 기말고사 50% 등 공식 비율 적용.",
    "guide.s2Li2": "총점제: 총 획득 점수를 총 배점 만점으로 나누는 방식.",
    "guide.s2Li3": "최저점 제외: 퀴즈나 과제 중 가장 낮은 점수를 자동으로 제외하는 학칙 지원.",
    "guide.s2P3": "비중이 큰 시험이 최종 학점에 미치는 실질적인 영향을 정확하게 계산합니다.",
    "guide.s3Title": "기말고사 목표 점수 계산기로 원하는 학점 달성하기",
    "guide.s3P1": "종강을 앞두고 가장 궁금한 질문은 \"A학점을 받으려면 기말고사에서 몇 점을 받아야 할까?\"입니다.",
    "guide.s3P2": "당사의 검증된 대수학 계산 공식을 사용합니다:",
    "guide.s3Formula": "기말고사 필요 점수 = (목표 최종 점수 − 현재 점수 × (1 − 기말고사 가중치)) / 기말고사 가중치",
    "guide.s3P3": "비교 매트릭스를 통해 각 등급별 필요 점수와 달성 난이도를 즉시 파악할 수 있습니다.",
    "guide.s4Title": "대학 학점 계산 및 학기 GPA 계획",
    "guide.s4P1": "개별 과목뿐 아니라 학기 전체 과목과 누적 GPA를 종합적으로 관리하세요.",
    "guide.s4P2": "표준 4.0 학점, 아너스(+0.5), 심화 AP(+1.0) 가중치를 모두 지원합니다.",
    "guide.s4P3": "What-If 슬라이더로 시험 전 다양한 점수 시나리오를 미리 시험해 볼 수 있습니다.",
