    "about.title": "회사 소개 - GradeCalculatorFinalX",
    "about.desc": "GradeCalculatorFinalX의 비전과 완전 프라이버시 보호 기능, 전 세계 학생과 교육자를 위한 무료 도구에 대해 알아보세요.",
    "about.eyebrow": "우리의 이야기와 사명",
    "about.h1": "GradeCalculatorFinalX 소개",
    "about.lead": "고등학생과 대학생을 위한 수학적으로 검증된 안전하고 직관적인 성적 계산 도구입니다.",
    "about.missionTitle": "우리의 사명",
    "about.missionP1": "GradeCalculatorFinalX(gradecalculatorfinalx.com)의 사명은 명확합니다. 학기 말 성적 계산의 불안감을 완전히 해소하는 것입니다.",
    "about.missionP2": "복잡한 강의계획서의 가중치 공식을 실시간 인터랙티브 도구로 변환하여, 학생이 수작업 계산 대신 본연의 학습에 집중할 수 있도록 돕습니다.",
    "about.whyTitle": "개발 배경",
    "about.whyP1": "기존의 복잡한 스프레드시트나 광고 가득한 웹사이트를 대체하는 완벽한 도구를 만들고자 했습니다:",
    "about.whyLi1": "완전한 개인정보 보호: 모든 계산은 브라우저(클라이언트 측)에서 로컬로 수행되며 외부 서버로 성적이 전송되지 않습니다.",
    "about.whyLi2": "다양한 평가 방식 지원: 백분율 가중치 및 점수 총점제 간 간편 전환 및 최하점 자동 제외 지원.",
    "about.whyLi3": "기말고사 목표 역산: 희망 학점 등급(A, B, C, 통과)에 필요한 기말고사 최소 점수를 즉시 계산.",
    "about.whyLi4": "학기 및 누적 GPA: 표준 4.0, 아너스(+0.5), AP/대학 심화(+1.0) 가중 평점 지원.",
    "about.precisionTitle": "신뢰할 수 있는 수학적 정밀도",
    "about.precisionP1": "저희 계산 엔진은 국제 대학 평가 기준에 따라 철저히 검증되었습니다.",
    "about.precisionCard1Title": "가중 평가 엔진",
    "about.precisionCard1Desc": "학기 중 완료된 과제 비율에 맞춰 자동으로 정규화하여 현재 성적을 정확히 표시합니다.",
    "about.precisionCard2Title": "목표 시험 역산 솔버",
    "about.precisionCard2Desc": "대수학적 역산 방식을 통해 목표 등급 달성에 필요한 기말고사 점수를 산출합니다.",
    "about.communityTitle": "학생과 교육자를 위해 설계",
    "about.communityP1": "수많은 대학생과 진로 상담사들이 중간고사 및 장학금 목표 관리에 활용하고 있습니다.",
    "about.communityP2": "새로운 기능 제안이나 제휴 문의는 문의하기 페이지를 이용해 주세요.",
    "privacy.title": "개인정보 처리방침 - GradeCalculatorFinalX",
    "privacy.desc": "GradeCalculatorFinalX의 개인정보 처리방침. 제로 트래킹 및 학생 데이터 완전 보호 원칙 안내.",
    "privacy.eyebrow": "투명성과 보안",
    "privacy.h1": "개인정보 처리방침",
    "privacy.s1Title": "1. 서론 및 프라이버시 기본 원칙",
    "privacy.s1P1": "GradeCalculatorFinalX에 오신 것을 환영합니다. 이용자의 개인정보를 소중히 보호합니다.",
    "privacy.s1P2": "회원가입이나 서버 저장이 필요 없으며, 모든 계산은 이용자의 기기 내에서만 처리됩니다.",
    "privacy.s2Title": "2. 수집하지 않는 정보",
    "privacy.s2P1": "당사는 다음 정보를 수집, 저장 또는 전송하지 않습니다:",
    "privacy.s2Li1": "개인 성적, 시험 점수 및 가중치 비율",
    "privacy.s2Li2": "과목명, 교수명 또는 소속 교육기관명",
    "privacy.s2Li3": "학번 및 공식 성적 증명 기록",
    "privacy.s2Li4": "비밀번호 및 전화번호",
    "privacy.s3Title": "3. LocalStorage 및 로컬 데이터 저장",
    "privacy.s3P1": "과목 정보 자동 저장을 위해 브라우저의 표준 LocalStorage 기능을 사용합니다.",
    "privacy.s3P2": "데이터는 이용자의 브라우저 내에만 유지되며 언제든지 초기화할 수 있습니다.",
    "privacy.s4Title": "4. URL 해시를 통한 안전한 공유",
    "privacy.s4P1": "공유 링크 생성 시 데이터는 URL 해시(#data=...)에 암호화되어 서버로 전달되지 않습니다.",
    "privacy.s5Title": "5. 쿠키 및 서버 로그",
    "privacy.s5P1": "추적용 상업 광고 쿠키는 사용하지 않습니다.",
    "privacy.s6Title": "6. 아동 온라인 개인정보 보호(COPPA) 준수",
    "privacy.s6P1": "13세 미만 아동의 개인정보를 수집하지 않으며 관련 법령을 엄격히 준수합니다.",
    "privacy.s7Title": "7. 개인정보 관련 문의",
    "privacy.s7P1": "문의사항은 문의하기 페이지 또는 privacy@gradecalculatorfinalx.com 으로 연락 바랍니다.",
