    "pcttocgpa.guide_heading": "백분율을 CGPA로 변환하는 방법",
    "pcttocgpa.guide_p1": "AICTE 가이드라인에 따라 9.5로 나누는 역연산이 적용됩니다:",
    "pcttocgpa.formula": "추정 CGPA = 백분율 (%) ÷ 9.5",
    "pcttocgpa.guide_p2": "예를 들어 총점 85.5%를 획득한 학생의 경우:",
    "pcttocgpa.example_res": "CGPA = 85.5 ÷ 9.5 = 9.00 / 10.00 (A+ 등급 / 우등)",
    "pcttocgpa.caveat_heading": "정확도 관련 유의사항",
    "pcttocgpa.caveat_p": "CGPA는 과목별 학점 가중치로 결정되므로 동일한 백분율 점수라도 실제 CGPA는 약간 다를 수 있습니다.",
    "pcttocgpa.faq_heading": "자주 묻는 질문",
    "pcttocgpa.faq1_q": "75%는 CGPA로 얼마인가요?",
    "pcttocgpa.faq1_a": "AICTE 기준: 75 ÷ 9.5 = 7.89 CGPA 입니다. 10점 직접 스케일에서는 7.50 CGPA 입니다.",
    "pcttocgpa.faq2_q": "60% 점수는 CGPA로 얼마인가요?",
    "pcttocgpa.faq2_a": "AICTE 기준: 60 ÷ 9.5 = 6.32 CGPA (1등급) 입니다.",
    "pcttocgpa.faq3_q": "70% 점수는 10점 CGPA로 얼마인가요?",
    "pcttocgpa.faq3_a": "AICTE 9.5 규칙에 따라 70 ÷ 9.5 = 7.37 CGPA 입니다.",
    "pcttocgpa.faq4_q": "VTU CGPA로 변환하려면 어떻게 하나요?",
    "pcttocgpa.faq4_a": "역공식: CGPA = (백분율 ÷ 10) + 0.75 입니다. 75%의 경우 (75 ÷ 10) + 0.75 = 8.25 VTU CGPA가 됩니다.",
    "pcttocgpa.related_heading": "관련 계산기",
    "icgpa.title": "인도 CGPA 계산기 - UGC 10점 만점 기준",
    "icgpa.guide_heading": "인도 10점 CGPA 계산 방법",
    "icgpa.guide_p1": "인도 고등교육 시스템은 Choice Based Credit System (CBCS)에 따라 학업 성취도를 평가합니다.",
    "icgpa.guide_p2": "각 과목은 학점 가중치를 가지며 알파벳 등급과 포인트가 부여됩니다:",
