    "converter.guide_heading": "국제 학점 변환의 이해",
    "converter.guide_p1": "WES와 같은 전문 평가 기관 및 대학 입학처는 단순 비례식이 아닌 현지 평가 기준에 맞춰 성적을 사정합니다.",
    "converter.guide_p2": "예를 들어 인도 대학의 70% 또는 8.0 CGPA는 최우등이지만, 미국에서는 70%가 C-에 해당합니다. 본 변환 매트릭스는 공식 사정 기준을 반영합니다.",
    "converter.faq_heading": "자주 묻는 질문",
