    "converter.faq1_a": "WES 가이드라인에 따르면 8.0/10.0은 4.0 만점 기준 약 3.50~3.70 GPA에 해당합니다.",
    "converter.faq2_q": "미국 대학은 CGPA를 단순 비례식으로 변환하나요?",
    "converter.faq2_a": "아닙니다. 과목별 백분위 분포와 성적 체계를 감안하여 과목 단위로 환산합니다.",
    "converter.faq3_q": "4.0과 5.0 GPA 스케일의 차이점은 무엇인가요?",
    "converter.faq3_a": "4.0은 비가중 표준 스케일이며, 5.0은 AP/IB 등 심화 과목에 가중치를 둔 스케일입니다.",
    "converter.faq4_q": "WES는 인도 10점 CGPA를 어떻게 사정하나요?",
    "converter.faq4_a": "성적표의 각 과목을 미국 등급(A, B, C)으로 변환한 후 학점으로 가중 평균하여 산출합니다.",
    "converter.related_heading": "관련 계산기",
