    "guide.s1Title": "Cos’è un Calcolatore di Voti Finale e Come Funziona?",
    "guide.s1P1": "Monitorare la propria carriera accademica richiede di conoscere esattamente la media prima della sessione d’esami. Un calcolatore di voti finale è uno strumento indispensabile per pianificare lo studio.",
    "guide.s1P2": "Su Grade Calculator FinalX combiniamo un calcolatore intuitivo di media ponderata con un pianificatore di voto d’esame affidabile e veloce.",
    "guide.s2Title": "Media Ponderata vs Media Aritmetica Semplice",
    "guide.s2P1": "Calcolare i voti con la media aritmetica semplice è fuorviante quando esami o verifiche hanno pesi e crediti diversi.",
    "guide.s2P2": "Con il nostro calcolatore ponderato assegni il peso esatto a ogni prova :",
    "guide.s2Li1": "Ponderazione Percentuale: Compiti 20%, prove intermedie 30%, esame finale 50%.",
    "guide.s2Li2": "Sistema a Punti: Punti totalizzati divisi per i punti massimi.",
    "guide.s2Li3": "Scarto del Voto Più Basso: Esclusione automatica della verifica peggiore.",
    "guide.s2P3": "Le prove più importanti ottengono il giusto peso matematico nella tua media finale.",
    "guide.s3Title": "Calcolare il Voto Necessario all’Esame Finale",
    "guide.s3P1": "La domanda che ogni studente si pone è: \"Che voto devo prendere all’esame per raggiungere il mio obiettivo?\"",
    "guide.s3P2": "La nostra formula algebrica calcola l’obiettivo esatto :",
    "guide.s3Formula": "Voto Necessario = (Voto Finale Desiderato − Voto Attuale × (1 − Peso Esame)) / Peso Esame",
    "guide.s3P3": "La matrice di scenari confronta la tua media attuale con tutti i punteggi possibili.",
    "guide.s4Title": "Calcolo Voti Universitari e Pianificazione GPA",
    "guide.s4P1": "Tieni traccia contemporaneamente dei corsi del semestre e del GPA cumulativo.",
    "guide.s4P2": "Supporta crediti CFU, scale 4.0 e corsi avanzati con punteggi extra.",
    "guide.s4P3": "Il cursore What-If simula i punteggi prima di sostenere le prove.",
