    "converter.faq2_q": "Le università USA convertono il CGPA direttamente?",
    "converter.faq2_a": "No, convertono corso per corso tenendo conto delle percentuali di superamento del paese d'origine.",
    "converter.faq3_q": "Qual è la differenza tra scala GPA 4.0 e 5.0?",
    "converter.faq3_a": "4.0 è lo standard non ponderato; 5.0 assegna pesi extra a corsi avanzati (AP/IB/Honors).",
    "converter.faq4_q": "Come valuta WES il CGPA indiano su 10 punti?",
